		}
		if !heredocMarkerRegexp.Match([]byte(heredocMarker)) {
			return false, fmt.Errorf("heredoc marker on line #%d must contain only alpha-numeric characters, dashes and underscores; got '%s'", l.line, heredocMarker)
		}

		inHeredoc = true
		l.skippedLines++
		val = nil
		continue
	}
	// the heredoc marker must be the last thing on the line; if
	// we encounter whitespace before a newline, this is just a
	// normal token (for example, "<< >>" used by the templates
	// directive), not a heredoc
	if unicode.IsSpace(ch) {
		return makeToken(0), nil
	}
	val = append(val, ch)
	continue
}

